import {useCallback,useEffect,useMemo,useState} from 'react';
import {Archive,BookOpen,CheckCircle2,ClipboardCheck,Plus,Search} from 'lucide-react';
import {archiveProfessionalResource,assignProfessionalResource,createClientHomework,createProfessionalResource,getClientAdherence,listClientHomework,listProfessionalResources,updateClientHomework,updateProfessionalResource} from '../../lib/practiceOperationsApi';

const TYPES=['PDF','DOCUMENT','VIDEO_LINK','ARTICLE_LINK','WORKSHEET','EXERCISE','INSTRUCTION','CHECKLIST','AUDIO_LINK','FORM_LINK'];
const HOMEWORK_TYPES=['CHECKLIST','REFLECTION','JOURNAL','EXERCISE','HABIT','OBSERVATION_LOG','EDUCATION_TASK','PRACTICE_ACTIVITY','CUSTOM'];
const HOMEWORK_STATUSES=['NOT_STARTED','IN_PROGRESS','COMPLETED','MISSED','CANCELLED'];
const initialResource={scope:'PRACTICE',title:'',description:'',resource_type:'INSTRUCTION',content_reference:'',tags:[]};
const initialHomework={title:'',description:'',homework_type:'CUSTOM',instructions:'',start_date:new Date().toISOString().slice(0,10),due_date:'',cadence:'ONE_TIME'};
const label=value=>String(value||'').replaceAll('_',' ').toLowerCase();
function Empty({children}){return <div className="rounded-2xl border border-dashed border-slate-300 bg-white p-8 text-center text-sm text-slate-600">{children}</div>}
function Failure({message,retry}){return <div role="alert" className="rounded-2xl border border-amber-200 bg-amber-50 p-5"><strong>Resources unavailable</strong><p className="mt-1 text-sm">{message}</p><button onClick={retry} className="mt-4 min-h-11 rounded-xl bg-amber-900 px-4 font-semibold text-white">Retry</button></div>}

export function ResourceLibrary({clients=[]}){
  const [items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[scope,setScope]=useState(''),[type,setType]=useState(''),[query,setQuery]=useState(''),[editor,setEditor]=useState(null),[assign,setAssign]=useState(null),[preview,setPreview]=useState(null);
  const load=useCallback(async()=>{setState('loading');setError('');try{const result=await listProfessionalResources({scope,resource_type:type,active:true});setItems(result.items||[]);setState('ready')}catch(reason){setError(reason.message);setState('error')}},[scope,type]);
  useEffect(()=>{void load()},[load]);
  const visible=useMemo(()=>items.filter(item=>!query||`${item.title} ${item.description||''} ${(item.tags||[]).join(' ')}`.toLowerCase().includes(query.toLowerCase())),[items,query]);
  const save=async event=>{event.preventDefault();setError('');try{const payload={...editor,tags:String(editor.tags||'').split(',').map(value=>value.trim()).filter(Boolean)};if(editor.id)await updateProfessionalResource(editor.id,payload);else await createProfessionalResource(payload);setEditor(null);await load()}catch(reason){setError(reason.message)}};
  const duplicate=async item=>{await createProfessionalResource({scope:item.scope==='SYSTEM'?'PRACTICE':item.scope,profession_code:item.profession_code,title:`${item.title} copy`,description:item.description,resource_type:item.resource_type,content_reference:item.content_reference,media_type:item.media_type,duration_minutes:item.duration_minutes,instructions:item.instructions,tags:item.tags||[],capability_required:item.capability_required});await load()};
  const assignNow=async event=>{event.preventDefault();try{await assignProfessionalResource(assign.client_id,{resource_id:assign.resource.id,context_type:'CLIENT',instructions:assign.instructions,required:assign.required});setAssign(null)}catch(reason){setError(reason.message)}};
  return <div className="space-y-5"><header className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-blue-700">Professional toolkit</p><h2 className="mt-1 text-3xl font-semibold tracking-tight">Resource Library</h2><p className="mt-2 text-sm text-slate-600">Reusable, version-bound resources for client work.</p></div><button onClick={()=>setEditor({...initialResource})} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-slate-950 px-4 font-semibold text-white"><Plus size={17}/>Create custom</button></header>
    <div className="grid gap-3 rounded-2xl border bg-white p-4 sm:grid-cols-[1fr_180px_180px]"><label className="relative"><Search className="absolute left-3 top-3.5" size={17}/><span className="sr-only">Search resources</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search resources" className="min-h-11 w-full rounded-xl border pl-10 pr-3"/></label><select aria-label="Resource scope" value={scope} onChange={e=>setScope(e.target.value)} className="min-h-11 rounded-xl border px-3"><option value="">All scopes</option><option>SYSTEM</option><option>PRACTICE</option><option>PRACTITIONER</option></select><select aria-label="Resource type" value={type} onChange={e=>setType(e.target.value)} className="min-h-11 rounded-xl border px-3"><option value="">All types</option>{TYPES.map(value=><option key={value}>{value}</option>)}</select></div>
    {state==='loading'?<div aria-label="Loading resources" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{[1,2,3].map(i=><div key={i} className="h-44 animate-pulse rounded-3xl bg-white"/>)}</div>:state==='error'?<Failure message={error} retry={load}/>:visible.length===0?<Empty>No confirmed resources match these filters.</Empty>:<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{visible.map(item=><article key={item.id} className="flex min-h-52 flex-col rounded-3xl border bg-white p-5 shadow-sm"><div className="flex justify-between gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-blue-50 text-blue-700"><BookOpen size={19}/></span><span className="text-xs font-bold text-slate-500">{item.scope}</span></div><h3 className="mt-4 font-semibold">{item.title}</h3><p className="mt-1 line-clamp-2 text-sm text-slate-600">{item.description||'No description'}</p><p className="mt-3 text-xs text-slate-500">{label(item.resource_type)} · version {item.version}</p><div className="mt-auto flex flex-wrap gap-2 pt-4"><button onClick={()=>setAssign({resource:item,client_id:clients[0]?.id||'',instructions:'',required:false})} className="min-h-11 flex-1 rounded-xl bg-blue-700 px-3 text-sm font-semibold text-white">Assign</button><button onClick={()=>setPreview(item)} className="min-h-11 rounded-xl border px-3 text-sm font-semibold">Preview</button><button onClick={()=>duplicate(item)} className="min-h-11 rounded-xl border px-3 text-sm font-semibold">Duplicate</button>{item.scope!=='SYSTEM'&&<><button onClick={()=>setEditor({...item,tags:(item.tags||[]).join(', ')})} className="min-h-11 rounded-xl border px-3 text-sm font-semibold">Edit</button><button aria-label={`Archive ${item.title}`} onClick={async()=>{await archiveProfessionalResource(item.id);await load()}} className="grid h-11 w-11 place-items-center rounded-xl border"><Archive size={16}/></button></>}</div></article>)}</div>}
    {error&&state!=='error'&&<p role="alert" className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}
    {preview&&<div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/45 sm:place-items-center sm:p-4"><section role="dialog" aria-modal="true" aria-label="Resource preview" className="w-full max-w-xl rounded-t-3xl bg-white p-6 sm:rounded-3xl"><p className="text-xs font-bold uppercase text-blue-700">{label(preview.resource_type)} · version {preview.version}</p><h3 className="mt-2 text-2xl font-semibold">{preview.title}</h3><p className="mt-3 text-sm text-slate-600">{preview.description||'No description provided.'}</p>{preview.instructions&&<p className="mt-4 rounded-xl bg-slate-50 p-4 text-sm">{preview.instructions}</p>}<button onClick={()=>setPreview(null)} className="mt-6 min-h-11 w-full rounded-xl bg-slate-950 font-semibold text-white">Close preview</button></section></div>}
    {editor&&<div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/45 sm:place-items-center sm:p-4"><form onSubmit={save} className="max-h-[92vh] w-full max-w-xl space-y-4 overflow-auto rounded-t-3xl bg-white p-5 sm:rounded-3xl sm:p-6"><h3 className="text-xl font-semibold">Create custom resource</h3><label className="block text-sm font-semibold">Title<input required value={editor.title} onChange={e=>setEditor({...editor,title:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"/></label><div className="grid gap-3 sm:grid-cols-2"><label className="text-sm font-semibold">Scope<select value={editor.scope} onChange={e=>setEditor({...editor,scope:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"><option>PRACTICE</option><option>PRACTITIONER</option></select></label><label className="text-sm font-semibold">Type<select value={editor.resource_type} onChange={e=>setEditor({...editor,resource_type:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3">{TYPES.map(value=><option key={value}>{value}</option>)}</select></label></div><label className="block text-sm font-semibold">Content reference<input required value={editor.content_reference} onChange={e=>setEditor({...editor,content_reference:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"/></label><label className="block text-sm font-semibold">Description<textarea value={editor.description} onChange={e=>setEditor({...editor,description:e.target.value})} className="mt-2 w-full rounded-xl border p-3"/></label><label className="block text-sm font-semibold">Tags<input value={editor.tags} onChange={e=>setEditor({...editor,tags:e.target.value})} placeholder="sleep, mobility" className="mt-2 min-h-11 w-full rounded-xl border px-3"/></label><div className="flex justify-end gap-2"><button type="button" onClick={()=>setEditor(null)} className="min-h-11 rounded-xl border px-4">Cancel</button><button className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white">Create</button></div></form></div>}
    {assign&&<div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/45 sm:place-items-center sm:p-4"><form onSubmit={assignNow} className="w-full max-w-lg space-y-4 rounded-t-3xl bg-white p-5 sm:rounded-3xl"><h3 className="text-xl font-semibold">Assign {assign.resource.title}</h3><label className="block text-sm font-semibold">Client<select required value={assign.client_id} onChange={e=>setAssign({...assign,client_id:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"><option value="">Choose client</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label><label className="block text-sm font-semibold">Instructions<textarea value={assign.instructions} onChange={e=>setAssign({...assign,instructions:e.target.value})} className="mt-2 w-full rounded-xl border p-3"/></label><label className="flex min-h-11 items-center gap-3"><input type="checkbox" checked={assign.required} onChange={e=>setAssign({...assign,required:e.target.checked})}/>Required</label><div className="flex justify-end gap-2"><button type="button" onClick={()=>setAssign(null)} className="min-h-11 rounded-xl border px-4">Cancel</button><button className="min-h-11 rounded-xl bg-blue-700 px-4 font-semibold text-white">Assign</button></div></form></div>}
  </div>;
}

export function ClientHomeworkAdherence({clientId}){
  const [homework,setHomework]=useState([]),[adherence,setAdherence]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[editor,setEditor]=useState(null);
  const load=useCallback(async()=>{setState('loading');setError('');const [h,a]=await Promise.allSettled([listClientHomework(clientId),getClientAdherence(clientId)]);if(h.status==='rejected'){setError(h.reason.message);setState('error');return}setHomework(h.value.items||[]);setAdherence(a.status==='fulfilled'?a.value.windows||[]:[]);setState(a.status==='fulfilled'?'ready':'partial')},[clientId]);useEffect(()=>{void load()},[load]);
  const save=async event=>{event.preventDefault();await createClientHomework(clientId,{...editor,due_date:editor.due_date||null});setEditor(null);await load()};
  if(state==='loading')return <div className="rounded-2xl bg-white p-10 text-center">Loading homework and adherence…</div>;
  if(state==='error')return <Failure message={error} retry={load}/>;
  return <div className="space-y-5">{state==='partial'&&<p role="status" className="rounded-xl bg-amber-50 p-3 text-sm">Homework loaded; adherence summary is temporarily unavailable.</p>}<div className="grid gap-3 sm:grid-cols-2">{adherence.map(item=><article key={item.window_type} className="rounded-2xl border bg-white p-5"><p className="text-xs font-bold uppercase text-slate-500">{label(item.window_type)}</p><p className="mt-2 text-3xl font-semibold">{item.completion_rate==null?'—':`${item.completion_rate}%`}</p><p className="mt-2 text-sm text-slate-600">{item.completed_count} completed · {item.missed_count} missed · {item.assigned_count} assigned</p><p className="mt-3 font-semibold">{label(item.label)}</p></article>)}</div><div className="flex justify-between"><div><h3 className="text-xl font-semibold">Homework</h3><p className="text-sm text-slate-600">Client-facing assigned activities, separate from practice tasks.</p></div><button onClick={()=>setEditor({...initialHomework})} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-slate-950 px-4 font-semibold text-white"><Plus size={16}/>Assign</button></div>{homework.length===0?<Empty>No homework has been assigned.</Empty>:<div className="space-y-3">{homework.map(item=><article key={item.id} className="rounded-2xl border bg-white p-4"><div className="flex flex-col justify-between gap-3 sm:flex-row"><div><h4 className="font-semibold">{item.title}</h4><p className="mt-1 text-sm text-slate-600">{label(item.homework_type)} · {label(item.cadence)} · {item.due_date||'No due date'}</p></div><span className="text-sm font-bold text-blue-700">{label(item.status)}</span></div>{!['COMPLETED','MISSED','CANCELLED'].includes(item.status)&&<div className="mt-4 flex flex-wrap gap-2"><button onClick={async()=>{await updateClientHomework(clientId,item.id,'COMPLETED');await load()}} className="min-h-11 rounded-xl bg-emerald-700 px-4 text-sm font-semibold text-white">Complete</button><button onClick={async()=>{await updateClientHomework(clientId,item.id,'MISSED');await load()}} className="min-h-11 rounded-xl border px-4 text-sm font-semibold">Mark missed</button><button onClick={async()=>{await updateClientHomework(clientId,item.id,'CANCELLED');await load()}} className="min-h-11 rounded-xl border px-4 text-sm font-semibold text-red-700">Cancel</button></div>}</article>)}</div>}
    {editor&&<div className="fixed inset-0 z-50 grid place-items-end bg-slate-950/45 sm:place-items-center sm:p-4"><form onSubmit={save} className="max-h-[92vh] w-full max-w-xl space-y-4 overflow-auto rounded-t-3xl bg-white p-5 sm:rounded-3xl"><h3 className="text-xl font-semibold">Assign homework</h3><label className="block text-sm font-semibold">Title<input required value={editor.title} onChange={e=>setEditor({...editor,title:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"/></label><label className="block text-sm font-semibold">Type<select value={editor.homework_type} onChange={e=>setEditor({...editor,homework_type:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3">{HOMEWORK_TYPES.map(value=><option key={value}>{value}</option>)}</select></label><div className="grid gap-3 sm:grid-cols-2"><label className="text-sm font-semibold">Start date<input type="date" value={editor.start_date} onChange={e=>setEditor({...editor,start_date:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"/></label><label className="text-sm font-semibold">Due date<input type="date" value={editor.due_date} onChange={e=>setEditor({...editor,due_date:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"/></label></div><label className="block text-sm font-semibold">Cadence<select value={editor.cadence} onChange={e=>setEditor({...editor,cadence:e.target.value})} className="mt-2 min-h-11 w-full rounded-xl border px-3"><option>ONE_TIME</option><option>DAILY</option><option>WEEKLY</option><option>CUSTOM_INTERVAL</option></select></label><label className="block text-sm font-semibold">Instructions<textarea value={editor.instructions} onChange={e=>setEditor({...editor,instructions:e.target.value})} className="mt-2 w-full rounded-xl border p-3"/></label><div className="flex justify-end gap-2"><button type="button" onClick={()=>setEditor(null)} className="min-h-11 rounded-xl border px-4">Cancel</button><button className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white">Assign homework</button></div></form></div>}
  </div>;
}
